head.script:
scwin.test_expression = function(value) {
    return value + "_test";
};
scwin.gridView1_ongroupby = function(options) {
    var flag = true;
    if (flag) {
        options.closeGroup = false;
        options.groupbyHeader = [{
            colSpan: "10",
            inputType: "expression",
            expression: " toggle() + depthStr() + ' [ '+ SUM('col3') +',' + count() + ' 건 ] ' ",
            align: "left"
        }];
        options.groupbyFooter = [{
                colSpan: "7"
            },
            {
                colSpan: "3",
                inputType: "expression",
                expression: " SUM('col3')",
                displayFormatter: "countFormatFunction",
                align: "center"
            }
        ];
        gridView1.groupby(options); //실제 groupby 실행
    } else {
        return false;
    }
};
scwin.countFormatFunction = function(value) {
    return "총판매수량 : " + value + " 개 ";
};
scwin.rgb2hex = function(rgb) {
    rgb = rgb.match(/^rgba?[\s+]?\([\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?/i);
    return (rgb && rgb.length === 4) ? "#" +
        ("0" + parseInt(rgb[1], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[2], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[3], 10).toString(16)).slice(-2) : '';
}
scwin._checkRgb = function(id, hexa) {
    var rgb = WebSquare.wUnit.getJq("#" + id).css("background-color");
    if (rgb.indexOf("rgb") != -1) {
        return rgb == "rgb(223, 233, 248)";
    }
    return rgb == hexa;
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#gridView1_column23', 'drag-n-drop', {
        dx: 0,
        dy: -50
    });
}
scwin.unitTest = function() {
    //Init test
    WebSquare.wUnit.start();
    //Test step 0. gridView의 속성 readOnly='true', readOnlyBackgroundColor='#dfe9f8'로 설정한다. - Set the properties of gridView readOnly = 'true', readOnlyBackgroundColor = 'skyblue'.
    //Test step 1. 샘플파일을 실행 후 'select'항목을 groupby 시킨 후 그리드뷰 색상을 확인한다.
    //1. Execute the sample file, groupby the 'select' item, and check the grid view color.
    //Verify 1. The row colors of label_a1, label_a2, and label_a3 that are grouped are displayed normally in skyblue color.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("assert", "scwin._checkRgb($p.id+'gridView1_cell_2_0', '#dfe9f8')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin._checkRgb($p.id+'gridView1_cell_5_0', '#dfe9f8')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin._checkRgb($p.id+'gridView1_cell_8_0', '#dfe9f8')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop unit Test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
        "col1": "a1",
        "col3": "10"
    }, {
        "col1": "a2",
        "col3": "20"
    }, {
        "col1": "a3",
        "col3": "30"
    }];
    dataList1.setJSON(jsonData);
    //Function unitTest
    //Created by Truong.Luu
    //Created date 23-Jan-2018            
    scwin.simulateWrapper = function(target, type, options) {
        WebSquare.wUnit.getJq(target).simulate(type, options);
    }
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
